package com.householdfinance.finance.adapter.config;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.nio.charset.*;import java.util.*;import javax.crypto.SecretKey;import org.springframework.boot.context.properties.*;import org.springframework.context.annotation.*;import org.springframework.security.authentication.*;import org.springframework.security.config.annotation.web.builders.*;import org.springframework.security.config.http.*;import org.springframework.security.core.authority.*;import org.springframework.security.core.context.*;import org.springframework.security.web.*;import org.springframework.security.web.authentication.*;import org.springframework.web.filter.OncePerRequestFilter;@Configuration @EnableConfigurationProperties(JwtProperties.class)public class SecurityConfig{@Bean SecurityFilterChain chain(HttpSecurity h,JwtProperties p)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/v3/api-docs/**","/swagger-ui/**").permitAll().anyRequest().authenticated()).addFilterBefore(new JwtFilter(p),UsernamePasswordAuthenticationFilter.class).build();}static class JwtFilter extends OncePerRequestFilter{final SecretKey k;final JwtProperties p;JwtFilter(JwtProperties p){this.p=p;k=Keys.hmacShaKeyFor(p.secret().getBytes(StandardCharsets.UTF_8));}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{var h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var x=Jwts.parser().verifyWith(k).build().parseSignedClaims(h.substring(7)).getPayload();if(p.issuer().equals(x.getIssuer())&&x.getAudience().contains(p.audience()))SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(x.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_USER"))));}catch(RuntimeException e){SecurityContextHolder.clearContext();}c.doFilter(r,s);}}}
